import{_ as e,o as t,c as a,a5 as i}from"./chunks/framework.Bkm3ODFN.js";const g=JSON.parse('{"title":"🌐 物联网引擎与多协议网关概述","description":"","frontmatter":{},"headers":[],"relativePath":"iot/overview.md","filePath":"iot/overview.md","lastUpdated":1794271174000}'),r={name:"iot/overview.md"};function l(d,o,s,n,c,u){return t(),a("div",null,[...o[0]||(o[0]=[i('<h1 id="🌐-物联网引擎与多协议网关概述" tabindex="-1">🌐 物联网引擎与多协议网关概述 <a class="header-anchor" href="#🌐-物联网引擎与多协议网关概述" aria-label="Permalink to &quot;🌐 物联网引擎与多协议网关概述&quot;">​</a></h1><p><code>yudao-module-iot</code> 是 MzMedia 的物联网核心子系统，负责工业物联网设备的连接、数据解析、物模型归一化抽象、高吞吐消息路由与自动化场景联动。</p><hr><h2 id="核心设计原则" tabindex="-1">核心设计原则 <a class="header-anchor" href="#核心设计原则" aria-label="Permalink to &quot;核心设计原则&quot;">​</a></h2><ol><li><strong>三层物理与逻辑解耦</strong>： <ul><li><strong><code>yudao-module-iot-core</code></strong>：核心抽象层，定义 TSL 物模型、设备消息体规范（<code>IotDeviceMessage</code>）与消息总线接口（<code>IotMessageBus</code>）；</li><li><strong><code>yudao-module-iot-gateway</code></strong>：协议接入层，实现 13+ 种工业协议的长连接接入与自定义编解码器；</li><li><strong><code>yudao-module-iot-biz</code></strong>：业务中台层，承载资产管理、设备影子、Modbus 定时点位调度、双核心规则引擎与 OTA 升级。</li></ul></li><li><strong>多协议即插即用</strong>： <ul><li>采用标准接口统一纳管所有协议网关实例，支持动态修改端口、线程池并在不重启服务的情况下热启停；</li></ul></li><li><strong>数据接入与业务完全解耦</strong>： <ul><li>底层设备报文上报后，网关层负责标准化为物模型属性、服务与事件，业务中台无须关心底层究竟是 Modbus 还是 MQTT。</li></ul></li></ol>',5)])])}const m=e(r,[["render",l]]);export{g as __pageData,m as default};
